import React from 'react';
import {
    AppStoreIcon, PlayStoreIcon, GearIcon, GoalIcon, TimelineIcon, BudgetIcon, PlannerIcon, DreamIcon, EventIcon, VisionBoardIcon, SelfCareIcon, ReviewIcon, NotesIcon, ReadingIcon
} from './components/IconComponents';
import { useState, useEffect, DragEvent, useMemo, useRef, MouseEvent, FormEvent, useCallback } from 'react';
import { GoogleGenAI, Type } from "@google/genai";
import { useCurrency } from './App';
import type { Currency } from './types';

// Data for the new interactive YearlyGoalsVisual
const goalNodes = {
    career: {
        id: 'career',
        name: 'Career',
        color: 'bg-sky-500',
        suggestions: [
            { S: 'Launch a new product line', M: 'Achieve $100k in presales', A: 'Develop MVP, marketing plan, and sales funnel', R: 'Relevant to Q3 company goals', T: 'Within 6 months' },
            { S: 'Get Promoted to Senior Dev', M: 'Lead 2 major feature releases', A: 'Mentor a junior dev, complete advanced certification', R: 'Aligns with career growth plan', T: 'Within 12 months' },
        ]
    },
    wellness: {
        id: 'wellness',
        name: 'Wellness',
        color: 'bg-emerald-500',
        suggestions: [
            { S: 'Complete a marathon', M: 'Follow a 20-week training plan consistently', A: 'Run 4x/week, strength train 2x/week, manage nutrition', R: 'Major personal health achievement', T: 'By October 30th' },
            { S: 'Meditate Daily', M: 'Log 30 consecutive days of 10-min sessions', A: 'Use a guided meditation app each morning', R: 'Improve focus and reduce stress', T: 'Within 6 weeks' },
        ]
    },
    legacy: {
        id: 'legacy',
        name: 'Legacy',
        color: 'bg-indigo-500',
        suggestions: [
            { S: 'Write a book', M: 'Complete a 50,000-word first draft', A: 'Write 500 words daily, outline all chapters', R: 'Share expertise with the world', T: 'By year-end' },
            { S: 'Start a non-profit', M: 'Secure initial funding and file for 501(c)(3) status', A: 'Build a board, define mission, create a website', R: 'Create lasting community impact', T: 'Within 9 months' },
        ]
    }
};

const testimonials = [
    { name: 'Alex R.', quote: 'From chaos to clarity in 90 days.', position: 'top-1/4 left-1/4' },
    { name: 'Jasmine K.', quote: 'I finally saw the big picture.', position: 'bottom-1/4 right-1/4' },
    { name: 'Samuel T.', quote: 'My goals became gravitational.', position: 'top-1/3 right-1/4' }
];

type GoalNodeKey = keyof typeof goalNodes;

// Visual components for each feature section
const YearlyGoalsVisual = () => {
    const [droppedNodes, setDroppedNodes] = useState<GoalNodeKey[]>([]);

    const handleDragStart = (e: DragEvent<HTMLDivElement>, nodeId: GoalNodeKey) => {
        e.dataTransfer.setData("nodeId", nodeId);
    };

    const handleDrop = (e: DragEvent<HTMLDivElement>) => {
        e.preventDefault();
        const nodeId = e.dataTransfer.getData("nodeId") as GoalNodeKey;
        if (nodeId && !droppedNodes.includes(nodeId)) {
            setDroppedNodes(prev => [...prev, nodeId]);
        }
    };

    const handleDragOver = (e: DragEvent<HTMLDivElement>) => {
        e.preventDefault();
    };

    return (
        <div className="w-full aspect-square md:aspect-auto md:h-[600px] p-4 flex flex-col lg:flex-row items-center justify-center gap-8 relative">
            {/* Left Panel: Draggable Nodes */}
            <div className="flex flex-row lg:flex-col gap-4 z-10">
                <p className="text-xs text-slate-400 font-bold uppercase tracking-wider text-center lg:text-left mb-2 hidden lg:block">Imprint Your Orbit</p>
                {Object.values(goalNodes).map(node => (
                    !droppedNodes.includes(node.id as GoalNodeKey) && (
                         <div
                            key={node.id}
                            draggable
                            onDragStart={(e) => handleDragStart(e, node.id as GoalNodeKey)}
                            className={`w-24 h-12 lg:w-32 lg:h-16 rounded-full flex items-center justify-center cursor-grab text-white font-bold text-sm ${node.color} shadow-lg transition-transform hover:scale-105`}
                        >
                            {node.name}
                        </div>
                    )
                ))}
            </div>

            {/* Right Panel: Observatory/Mind-map */}
            <div
                className="w-full h-full min-h-[350px] lg:min-h-0 bg-black/30 border border-slate-800 rounded-3xl shadow-2xl shadow-slate-900/50 relative flex items-center justify-center"
                onDrop={handleDrop}
                onDragOver={handleDragOver}
            >
                {/* Background Nebula */}
                <div className="absolute inset-0 bg-gradient-to-br from-indigo-900/20 via-slate-900/10 to-purple-900/20 opacity-50 rounded-3xl"></div>

                {/* Testimonial Constellations */}
                {testimonials.map((t, i) => (
                    <div key={i} className={`absolute ${t.position} text-center p-2 rounded-lg opacity-0`} style={{animation: `fadeIn 1s ease-out ${1 + i * 0.5}s forwards`}}>
                        <img src={`https://i.pravatar.cc/40?u=${t.name}`} alt={t.name} className="w-8 h-8 rounded-full mx-auto mb-1 border-2 border-slate-600"/>
                        <p className="text-xs text-slate-400 italic">"{t.quote}"</p>
                    </div>
                ))}

                {/* Central Core */}
                <div className="w-24 h-24 rounded-full bg-slate-800 flex items-center justify-center text-center shadow-inner">
                    <div className="w-20 h-20 rounded-full bg-slate-900 flex items-center justify-center animate-pulse">
                         <span className="text-slate-300 font-bold">CORE</span>
                    </div>
                </div>

                {/* Dropped/Orbiting Nodes */}
                {droppedNodes.map((nodeId, index) => {
                    const node = goalNodes[nodeId];
                    const animationName = `orbit${(index % 3) + 1}`;
                    return (
                        <div key={nodeId} className={`absolute top-1/2 left-1/2 -ml-6 -mt-6`} style={{ animation: `${animationName} ${15 + index*5}s linear infinite`}}>
                           <div className={`w-12 h-12 rounded-full ${node.color} flex items-center justify-center text-white text-xs font-bold`}>
                               {node.name}
                           </div>
                        </div>
                    );
                })}

                {/* AI Suggestions Box */}
                {droppedNodes.length > 0 && (
                    <div className="absolute bottom-4 left-4 right-4 bg-slate-900/80 backdrop-blur-sm border border-slate-700 p-3 rounded-lg z-20 opacity-0" style={{animation: 'fadeIn 1s ease-out 0.5s forwards'}}>
                        <h4 className="text-sm font-bold text-slate-300 mb-2 shimmer-bg rounded px-2">AI-Suggested SMART Breakdown:</h4>
                        <div className="text-xs text-slate-400 space-y-1">
                           {goalNodes[droppedNodes[droppedNodes.length - 1]].suggestions[0] &&
                                <p><strong className="text-slate-200">S:</strong> {goalNodes[droppedNodes[droppedNodes.length - 1]].suggestions[0].S}</p>
                           }
                           {goalNodes[droppedNodes[droppedNodes.length - 1]].suggestions[0] &&
                                <p><strong className="text-slate-200">M:</strong> {goalNodes[droppedNodes[droppedNodes.length - 1]].suggestions[0].M}</p>
                           }
                        </div>
                    </div>
                )}

                {droppedNodes.length === 0 && (
                    <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                        <p className="text-slate-600 text-lg font-medium">Drop a node to begin</p>
                    </div>
                )}
            </div>
        </div>
    );
};

const monthNames = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
const seasonalColors = [
    'border-sky-700', 'border-sky-600', 'border-teal-600', // Winter
    'border-pink-500', 'border-green-500', 'border-green-400', // Spring
    'border-yellow-400', 'border-orange-400', 'border-orange-500', // Summer
    'border-amber-600', 'border-red-600', 'border-indigo-700'  // Fall
];

const TimelineVisual = () => {
    const { formatCurrency } = useCurrency();
    const [activeMonth, setActiveMonth] = useState<number | null>(6);
    const [anchorText, setAnchorText] = useState('');
    const [anchors, setAnchors] = useState<Record<number, string>>({ 6: "Family Sabbatical" });
    const [simulatedBudget, setSimulatedBudget] = useState(10000); // Base currency is USD
    const [simulatedForecast, setSimulatedForecast] = useState("Q3 Growth: +15% Income");
    const [isAnimating, setIsAnimating] = useState(false);

    const handleSetAnchor = (e: React.FormEvent) => {
        e.preventDefault();
        if (!anchorText || activeMonth === null) return;

        setAnchors(prev => ({ ...prev, [activeMonth]: anchorText }));
        setIsAnimating(true);
        setSimulatedBudget(prev => prev - 2500);
        setSimulatedForecast("Q4 Surge Predicted");

        setTimeout(() => {
            setIsAnimating(false);
            setAnchorText('');
        }, 1500);
    };

    return (
        <div className="w-full h-[500px] flex flex-col lg:flex-row items-center justify-center gap-8 relative overflow-hidden p-4">
            {/* Left Side: Astrolabe Month Selector */}
            <div className="w-full lg:w-1/3 h-full flex items-center justify-center" style={{ perspective: '1000px' }}>
                <div className="relative w-full h-full" style={{ transformStyle: 'preserve-3d' }}>
                    {monthNames.map((month, i) => {
                        const isActive = activeMonth === i;
                        const offset = i - (activeMonth ?? 6);
                        const translateY = isActive ? 0 : offset * 30;
                        const scale = isActive ? 1.1 : 1 - Math.abs(offset) * 0.1;
                        const opacity = isActive ? 1 : Math.max(0, 1 - Math.abs(offset) * 0.2);
                        const zIndex = 12 - Math.abs(offset);

                        return (
                            <div
                                key={month}
                                onClick={() => setActiveMonth(i)}
                                className={`absolute inset-x-0 h-16 bg-slate-900/50 backdrop-blur-sm border-l-4 ${seasonalColors[i]} rounded-r-lg flex items-center px-4 cursor-pointer transition-all duration-500 ease-in-out`}
                                style={{
                                    top: '50%',
                                    marginTop: '-2rem',
                                    transform: `translateY(${translateY}px) translateZ(${isActive ? 100 : 0}px) scale(${scale})`,
                                    opacity,
                                    zIndex
                                }}
                            >
                                <span className="font-bold text-lg text-slate-200">{month}</span>
                            </div>
                        );
                    })}
                </div>
            </div>

            {/* Right Side: "Chronicle Your Epoch" Simulator */}
            <div className="w-full lg:w-2/3 h-full bg-slate-900/30 border border-slate-800 rounded-2xl flex flex-col justify-between p-6 relative">
                <div className="text-center">
                    <h3 className="font-bold text-xl text-slate-200">Chronicle Your Epoch</h3>
                    <p className="text-sm text-slate-400">Select a month, set a pivotal anchor, and watch the timeline harmonize.</p>
                </div>

                <div className="flex-grow flex flex-col items-center justify-center gap-4">
                    {activeMonth !== null && (
                        <div className="w-full max-w-sm text-center opacity-0" style={{ animation: 'fadeIn 0.5s forwards' }}>
                             <h4 className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-slate-200 to-slate-400 mb-4">{monthNames[activeMonth]}</h4>
                            {anchors[activeMonth] ? (
                                <p className="text-lg text-emerald-300 p-2 border border-emerald-700 rounded-md">Anchor: {anchors[activeMonth]}</p>
                            ) : (
                                <form onSubmit={handleSetAnchor} className="flex gap-2">
                                    <input
                                        type="text"
                                        value={anchorText}
                                        onChange={(e) => setAnchorText(e.target.value)}
                                        placeholder="e.g., Launch Project Phoenix"
                                        className="bg-slate-800 border border-slate-700 rounded-md py-2 px-3 text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-slate-500 flex-grow"
                                    />
                                    <button type="submit" className="bg-slate-200 text-black font-bold py-2 px-4 rounded-md hover:bg-white transition-colors">Set</button>
                                </form>
                            )}
                        </div>
                    )}
                </div>

                <div className="grid grid-cols-2 gap-4 text-center">
                    <div>
                        <p className="text-xs uppercase tracking-wider text-slate-500">AI Forecast</p>
                        <p className="text-lg font-semibold hologram-forecast">{simulatedForecast}</p>
                    </div>
                    <div>
                        <p className="text-xs uppercase tracking-wider text-slate-500">Simulated Budget</p>
                        <p className="text-lg font-semibold text-slate-300 transition-colors duration-500">{formatCurrency(simulatedBudget)}</p>
                    </div>
                </div>

                {/* Interlocking Gears Animation */}
                {isAnimating && (
                    <div className="absolute inset-0 bg-black/50 flex items-center justify-center opacity-0" style={{ animation: 'fadeIn 0.2s forwards' }}>
                        <div className="relative w-32 h-32">
                            <div className="absolute top-4 left-4 text-slate-600 gear-1"><GearIcon size={64}/></div>
                            <div className="absolute bottom-4 right-4 text-slate-700 gear-2"><GearIcon size={48}/></div>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

const BudgetAlchemyVisual = () => {
    type FinancialItem = { id: number; name: string; amount: number; }; // Amount is in USD
    type DebtItem = FinancialItem & { apr: number; };
    type Financials = {
        income: number; // USD
        expenses: { fixed: FinancialItem[]; variable: FinancialItem[]; };
        debts: DebtItem[];
        savings: FinancialItem[];
        goals: FinancialItem[];
    };

    const { currency, setCurrency, getSymbol, formatCurrency, convertFromUSD, convertToUSD, rates } = useCurrency();
    const [view, setView] = useState<'forge' | 'loading' | 'simulation'>('forge');
    const [financials, setFinancials] = useState<Financials>({
        income: 5000,
        expenses: { fixed: [{ id: 1, name: 'Rent', amount: 1500 }], variable: [{ id: 1, name: 'Groceries', amount: 400 }] },
        debts: [{ id: 1, name: 'Student Loan', amount: 20000, apr: 5.5 }],
        savings: [{ id: 1, name: 'Emergency Fund', amount: 3000 }],
        goals: [{ id: 1, name: 'Vacation', amount: 2500 }],
    });
    const [advice, setAdvice] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');
    const [whatIf, setWhatIf] = useState({ savingsBoost: 0 }); // In USD

    const ai = useMemo(() => new GoogleGenAI({ apiKey: process.env.API_KEY as string }), []);

    const handleAddItem = (category: 'expenses.fixed' | 'expenses.variable' | 'debts' | 'savings' | 'goals') => {
        const id = Date.now();
        const newItem = { id, name: 'New Item', amount: 0, ...(category === 'debts' && { apr: 0 }) };

        setFinancials(prev => {
            const newFinancials = { ...prev };
            let targetArray;
            if (category === 'expenses.fixed') targetArray = newFinancials.expenses.fixed;
            else if (category === 'expenses.variable') targetArray = newFinancials.expenses.variable;
            else if (category === 'debts') targetArray = newFinancials.debts;
            else if (category === 'savings') targetArray = newFinancials.savings;
            else targetArray = newFinancials.goals;

            // @ts-ignore
            targetArray.push(newItem);
            return newFinancials;
        });
    };

    const handleItemChange = (category: string, id: number, field: string, value: string | number) => {
        setFinancials(prev => {
            const newFinancials = JSON.parse(JSON.stringify(prev));
            let targetArray;
            if (category === 'expenses.fixed') targetArray = newFinancials.expenses.fixed;
            else if (category === 'expenses.variable') targetArray = newFinancials.expenses.variable;
            else if (category === 'debts') targetArray = newFinancials.debts;
            else if (category === 'savings') targetArray = newFinancials.savings;
            else if (category === 'goals') targetArray = newFinancials.goals;

            const item = targetArray.find((i: FinancialItem) => i.id === id);
            if (item) {
                // @ts-ignore
                item[field] = (field === 'name') ? value : Number(value);
            }
            return newFinancials;
        });
    };

    const handleTransmute = async (e: FormEvent) => {
        e.preventDefault();
        setView('loading');
        setIsLoading(true);
        setError('');
        setAdvice('');

        const toLocalCurrency = (amount: number) => convertFromUSD(amount).toFixed(2);
        const symbol = getSymbol();

        const prompt = `
            You are a world-class financial advisor AI, The Life Architect Oracle. Your advice is practical, empathetic, and empowering. Based on the following financial data (in ${currency}), provide a personalized and actionable financial plan in markdown format.

            **User's Financial Snapshot:**
            *   **Monthly Income:** ${symbol}${toLocalCurrency(financials.income)}
            *   **Fixed Monthly Expenses:**
                ${financials.expenses.fixed.map(item => `- ${item.name}: ${symbol}${toLocalCurrency(item.amount)}`).join('\n')}
            *   **Variable Monthly Expenses:**
                ${financials.expenses.variable.map(item => `- ${item.name}: ${symbol}${toLocalCurrency(item.amount)}`).join('\n')}
            *   **Debts:**
                ${financials.debts.map(debt => `- ${debt.name}: ${symbol}${toLocalCurrency(debt.amount)} at ${debt.apr}% APR`).join('\n')}
            *   **Current Savings:**
                ${financials.savings.map(item => `- ${item.name}: ${symbol}${toLocalCurrency(item.amount)}`).join('\n')}
            *   **Financial Goals:**
                ${financials.goals.map(goal => `- ${goal.name}: Target ${symbol}${toLocalCurrency(goal.amount)}`).join('\n')}

            **Your Task:**
            Generate a comprehensive financial plan covering these five key areas. Be encouraging and use headings for each section.

            1.  **### Spending Optimization Analysis**
                Identify 3-5 specific areas where spending can be cut or optimized. Provide realistic reduction targets in ${currency}.
            2.  **### Prioritized Debt Payoff Strategy**
                Recommend either the Avalanche or Snowball method, explain why it's a good fit, and create a clear, prioritized list of which debts to tackle first.
            3.  **### Automated Wealth-Building Plan**
                Suggest specific, automated actions for saving and investing. Recommend amounts in ${currency} for an emergency fund vs. long-term investments.
            4.  **### Income Growth Opportunities**
                Suggest 2-3 practical ways to potentially increase income.
            5.  **### Long-Term Vision & Sticking To It**
                Provide a motivational closing statement and practical tips for staying on track.
        `;

        try {
            const stream = await ai.models.generateContentStream({
                model: "gemini-2.5-flash",
                contents: prompt,
            });
            setView('simulation');
            for await (const chunk of stream) {
                setAdvice(prev => prev + chunk.text);
            }
        } catch (err) {
            console.error(err);
            setError("The financial cosmos is turbulent. Please try again later.");
            setView('forge');
        } finally {
            setIsLoading(false);
        }
    };

    const totals = useMemo(() => {
        const totalFixed = financials.expenses.fixed.reduce((sum, item) => sum + item.amount, 0);
        const totalVariable = financials.expenses.variable.reduce((sum, item) => sum + item.amount, 0);
        const totalExpenses = totalFixed + totalVariable;
        const netFlow = financials.income - totalExpenses;
        return { totalExpenses, netFlow }; // In USD
    }, [financials]);

    const InputSection: React.FC<{title: string, items: (FinancialItem[] | DebtItem[]), category: string}> = ({ title, items, category }) => (
        <fieldset className="border border-slate-700 p-3 rounded-lg">
            <legend className="px-2 text-sm font-bold text-slate-300">{title}</legend>
            <div className="space-y-2">
                {items.map(item => (
                    <div key={item.id} className="grid grid-cols-12 gap-2 items-center">
                        <input type="text" value={item.name} onChange={e => handleItemChange(category, item.id, 'name', e.target.value)} placeholder="Name" className="col-span-5 bg-slate-800 border border-slate-600 rounded px-2 py-1 text-xs focus:ring-1 focus:ring-slate-500 focus:outline-none" />
                        <input type="number" value={convertFromUSD(item.amount).toFixed(2)} onChange={e => handleItemChange(category, item.id, 'amount', convertToUSD(parseFloat(e.target.value) || 0))} placeholder="Amount" className="col-span-4 bg-slate-800 border border-slate-600 rounded px-2 py-1 text-xs focus:ring-1 focus:ring-slate-500 focus:outline-none" />
                        {'apr' in item ? (
                             <input type="number" value={item.apr} onChange={e => handleItemChange(category, item.id, 'apr', parseFloat(e.target.value) || 0)} placeholder="APR %" className="col-span-3 bg-slate-800 border border-slate-600 rounded px-2 py-1 text-xs focus:ring-1 focus:ring-slate-500 focus:outline-none" />
                        ) : <div className="col-span-3"></div>}
                    </div>
                ))}
            </div>
            <button type="button" onClick={() => handleAddItem(category as any)} className="mt-2 text-xs bg-slate-700 hover:bg-slate-600 rounded px-2 py-1 font-bold w-full">+ Add</button>
        </fieldset>
    );

    const renderView = () => {
        switch (view) {
            case 'loading':
                return (
                    <div className="flex flex-col items-center justify-center h-full text-center">
                        <div className="relative w-32 h-32">
                            <div className="absolute top-4 left-4 text-slate-600 gear-1"><GearIcon size={64}/></div>
                            <div className="absolute bottom-4 right-4 text-slate-700 gear-2"><GearIcon size={48}/></div>
                        </div>
                        <h3 className="text-xl font-bold text-slate-200 mt-4">Consulting the Financial Cosmos...</h3>
                        <p className="text-slate-400">Your personalized oracle is being forged.</p>
                    </div>
                );
            case 'simulation':
                const simulatedNetFlowUSD = totals.netFlow + whatIf.savingsBoost;
                const totalIncome = financials.income || 1;
                const expensePercent = Math.min(100, (totals.totalExpenses / totalIncome) * 100);
                const netPercent = 100 - expensePercent;

                const sliderMin = Math.round(convertFromUSD(-500));
                const sliderMax = Math.round(convertFromUSD(500));

                return (
                    <div className="flex flex-col lg:flex-row gap-6 w-full h-full p-2">
                        <div className="lg:w-1/3 flex flex-col gap-4">
                             <div className="bg-slate-900/50 p-4 rounded-lg border border-slate-700 text-center">
                                 <h4 className="text-xs uppercase tracking-wider text-slate-400">Simulated Net Flow</h4>
                                 <p className={`text-3xl font-bold transition-colors duration-300 ${simulatedNetFlowUSD >= 0 ? 'text-emerald-300' : 'text-rose-300'}`}>{formatCurrency(simulatedNetFlowUSD)}/mo</p>
                            </div>
                            <div className="bg-slate-900/50 p-4 rounded-lg border border-slate-700">
                                <h4 className="text-sm font-bold text-slate-300 mb-2 text-center">Cash Flow Vein</h4>
                                <div className="w-full bg-slate-800 rounded-full h-4 flex overflow-hidden border border-slate-700" title={`Expenses: ${expensePercent.toFixed(1)}%, Net: ${netPercent.toFixed(1)}%`}>
                                    <div className="bg-rose-500/80 transition-all duration-500" style={{ width: `${expensePercent}%` }}></div>
                                    <div className="bg-emerald-500/80 transition-all duration-500" style={{ width: `${netPercent}%` }}></div>
                                </div>
                            </div>
                            <div className="bg-slate-900/50 p-4 rounded-lg border border-slate-700">
                                <h4 className="text-sm font-bold text-slate-300 mb-2 text-center">'What If' Altar</h4>
                                 <div className="flex items-center gap-4">
                                    <span className="text-xs text-rose-400">{getSymbol()}{sliderMin}</span>
                                    <input id="whatif-slider" type="range" min={sliderMin} max={sliderMax} step={Math.max(1, Math.round(convertFromUSD(25)))} value={Math.round(convertFromUSD(whatIf.savingsBoost))} onChange={(e) => setWhatIf({savingsBoost: convertToUSD(parseInt(e.target.value))})} className="w-full" aria-label="What if scenario slider" />
                                    <span className="text-xs text-emerald-400">+{getSymbol()}{sliderMax}</span>
                                </div>
                                <p className="text-xs text-slate-500 text-center mt-1">Adjust monthly savings/debt payment</p>
                            </div>
                             <button onClick={() => setView('forge')} className="w-full text-center bg-slate-700 hover:bg-slate-600 rounded p-2 text-sm font-bold">Reforge Data</button>
                        </div>
                        <div className="lg:w-2/3 bg-slate-900/50 p-4 rounded-lg border border-slate-700 overflow-y-auto max-h-[450px] lg:max-h-full">
                             <h3 className="text-lg font-bold text-slate-200 mb-2">Oracle's Scroll</h3>
