// --- Project Modal Component ---
const ProjectModal: React.FC<{ project: Project | null; onClose: () => void }> = ({ project, onClose }) => {
    const videoRef = useRef<HTMLVideoElement>(null);
    const [isVideoError, setIsVideoError] = useState(false);
    const [mediaIndex, setMediaIndex] = useState(0);

    useEffect(() => {
        if (project) {
            setIsVideoError(false);
            setMediaIndex(0);
            document.body.style.overflow = 'hidden';
            setTimeout(() => {
                 videoRef.current?.play().catch(e => console.log("Autoplay was prevented."));
            }, 300);
        } else {
            document.body.style.overflow = 'auto';
        }
        return () => { document.body.style.overflow = 'auto'; };
    }, [project]);

    if (!project) return null;

    const renderMarkdown = (text: string) => {
        const lines = text.split('\n').filter(line => line.trim() !== '');
        const elements = [];
        let i = 0;
        while (i < lines.length) {
            const line = lines[i];

            if (line.startsWith('### ')) {
                elements.push(<h3 key={i} className="text-xl font-semibold text-slate-200 mt-4 mb-2">{line.substring(4)}</h3>);
                i++;
            } else if (line.startsWith('## ')) {
                elements.push(<h2 key={i} className="text-2xl font-bold text-slate-100 mt-6 mb-3 border-b border-slate-700 pb-2">{line.substring(3)}</h2>);
                i++;
            } else if (line.startsWith('* ')) {
                const listItems = [];
                while (i < lines.length && lines[i].startsWith('* ')) {
                    const itemLine = lines[i].substring(2);
                    const parts = itemLine.split('**');
                    const styledLine = parts.map((part, p_idx) => p_idx % 2 === 1 ? <strong key={p_idx} className="text-slate-100">{part}</strong> : part);
                    listItems.push(<li key={i}>{styledLine}</li>);
                    i++;
                }
                elements.push(<ul key={`ul-${i}`} className="list-disc pl-6 space-y-2 mb-4 text-slate-300">{listItems}</ul>);
            } else if (line.startsWith('```')) {
                const codeLines = [];
                i++; // move past the opening ```
                while (i < lines.length && !lines[i].startsWith('```')) {
                    codeLines.push(lines[i]);
                    i++;
                }
                i++; // move past the closing ```
                elements.push(
                    <pre key={`pre-${i}`} className="code-block-container bg-slate-800/50 p-4 rounded-md my-4 overflow-x-auto">
                        <code className="text-sm text-cyan-300 font-mono">{codeLines.join('\n')}</code>
                    </pre>
                );
            }
            else {
                const parts = line.split('**');
                const styledLine = parts.map((part, p_idx) => p_idx % 2 === 1 ? <strong key={p_idx} className="text-slate-100">{part}</strong> : part);
                elements.push(<p key={i} className="text-slate-300 mb-4 leading-relaxed">{styledLine}</p>);
                i++;
            }
        }
        return elements;
    };

    const media = [
        { type: 'video' as const, src: project.video, poster: project.poster },
        ...(project.gallery || []).map(url => ({ type: 'image' as const, src: url }))
    ];

    const hasMultipleMedia = media.length > 1;

    const nextMedia = () => setMediaIndex(prev => (prev + 1) % media.length);
    const prevMedia = () => setMediaIndex(prev => (prev - 1 + media.length) % media.length);

    return (
        <div className="fixed inset-0 bg-slate-900 z-50 modal-enter modal-enter-active" role="dialog" aria-modal="true" aria-labelledby="project-title">
            <div className="modal-content-enter modal-content-enter-active w-full h-full overflow-y-auto" onClick={e => { if(e.target === e.currentTarget) onClose() }}>
                <div className="relative w-full h-[60vh] bg-black">
                    <div className="w-full h-full overflow-hidden">
                        <div className="flex h-full transition-transform duration-500 ease-in-out" style={{ transform: `translateX(-${mediaIndex * 100}%)` }}>
                            {media.map((item, index) => (
                                <div key={index} className="w-full h-full flex-shrink-0">
                                    {item.type === 'video' ? (
                                        isVideoError ? (
                                            <img src={item.poster} alt={`${project.title} poster`} className="w-full h-full object-cover" />
                                        ) : (
                                            <video 
                                                ref={videoRef} 
                                                src={item.src} 
                                                poster={item.poster} 
                                                className="w-full h-full object-cover" 
                                                loop 
                                                muted 
                                                playsInline
                                                controls={mediaIndex === index}
                                                onError={() => setIsVideoError(true)}
                                            />
                                        )
                                    ) : (
                                        <img src={item.src} alt={`Project gallery image ${index}`} className="w-full h-full object-cover" />
                                    )}
                                </div>
                            ))}
                        </div>
                    </div>

                    <div className="absolute inset-0 bg-gradient-to-t from-slate-900 to-transparent pointer-events-none"></div>
                    <button onClick={onClose} className="absolute top-6 right-6 w-10 h-10 bg-black/50 rounded-full text-white text-2xl z-20" aria-label="Close project details">&times;</button>
                    <h2 id="project-title" className="absolute bottom-8 left-8 text-3xl md:text-5xl font-bold text-white pointer-events-none z-10">{project.title}</h2>

                    {hasMultipleMedia && (
                        <>
                            <button onClick={prevMedia} className="carousel-btn left-4">‹</button>
                            <button onClick={nextMedia} className="carousel-btn right-4">›</button>
                            <div className="carousel-dots">
                                {media.map((_, index) => (
                                    <button key={index} onClick={() => setMediaIndex(index)} className={`w-2.5 h-2.5 rounded-full transition-colors ${mediaIndex === index ? 'bg-white' : 'bg-white/50'}`}></button>
                                ))}
                            </div>
                        </>
                    )}
                </div>
                <div className="max-w-5xl mx-auto p-8">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                        <div className="md:col-span-2">
                            <p className="text-slate-300 mb-4">{project.plot}</p>
                            <div className="flex flex-wrap gap-4 mb-4">
                                <a href={project.liveUrl} target="_blank" rel="noopener noreferrer" className="bg-white text-black font-bold py-2 px-6 rounded hover:bg-gray-200 transition-colors">Watch Now</a>

                                {project.infographicsUrl && project.infographicsUrl !== "#" && (
                                    <a href={project.infographicsUrl} target="_blank" rel="noopener noreferrer" className="bg-gray-600/50 text-white font-bold py-2 px-6 rounded hover:bg-gray-600/80 transition-colors">Infographics</a>
                                )}

                                {project.brochureUrl && project.brochureUrl !== "#" && (
                                    <a href={project.brochureUrl} target="_blank" rel="noopener noreferrer" className="bg-gray-600/50 text-white font-bold py-2 px-6 rounded hover:bg-gray-600/80 transition-colors">Brochure</a>
                                )}

                                {project.githubUrl && project.githubUrl !== "#" && (
                                    <a href={project.githubUrl} target="_blank" rel="noopener noreferrer" className="bg-gray-600/50 text-white font-bold py-2 px-6 rounded hover:bg-gray-600/80 transition-colors">GitHub</a>
                                )}
