                            {/* Gallery Grid */}
                            {(project.gallery && project.gallery.length > 0) && (
                                <div className="mb-6">
                                    <h3 className="text-lg font-bold text-slate-200 mb-3 flex items-center gap-2">
                                        Gallery <span className="text-xs font-normal text-slate-500 bg-slate-800 px-2 py-0.5 rounded-full">{project.gallery.length + 1} Items</span>
                                    </h3>
                                    <div className="grid grid-cols-4 sm:grid-cols-5 md:grid-cols-6 gap-2">
                                        {/* Video Thumbnail */}
                                        <div 
                                            className={`relative aspect-square rounded-md overflow-hidden cursor-pointer border-2 transition-all duration-200 ${mediaIndex === 0 ? 'border-red-600 scale-95 opacity-100 ring-2 ring-red-600/20' : 'border-transparent hover:border-slate-500 opacity-70 hover:opacity-100'}`}
                                            onClick={() => setMediaIndex(0)}
                                            title="Play Video"
                                        >
                                            <img src={project.poster} alt="Video Thumbnail" className="w-full h-full object-cover" />
                                            <div className="absolute inset-0 flex items-center justify-center bg-black/30">
                                                <div className="w-8 h-8 bg-white/20 rounded-full flex items-center justify-center backdrop-blur-sm shadow-lg">
                                                    <svg className="w-4 h-4 text-white fill-current" viewBox="0 0 20 20"><path d="M6.3 2.841A1.5 1.5 0 004 4.11V15.89a1.5 1.5 0 002.3 1.269l9.344-5.89a1.5 1.5 0 000-2.538L6.3 2.84z"></path></svg>
                                                </div>
                                            </div>
                                        </div>

                                        {/* Gallery Images */}
                                        {project.gallery.map((url, idx) => (
                                            <div 
                                                key={idx} 
                                                className={`relative aspect-square rounded-md overflow-hidden cursor-pointer border-2 transition-all duration-200 ${mediaIndex === idx + 1 ? 'border-red-600 scale-95 opacity-100 ring-2 ring-red-600/20' : 'border-transparent hover:border-slate-500 opacity-70 hover:opacity-100'}`}
