                                            </div>
                                        ))}
                                    </div>
                                </div>
                            )}

                            {project.overview && (
                                <details className="group project-accordion">
                                    <summary className="flex justify-between items-center cursor-pointer py-2 font-semibold text-slate-200">
                                        Project Overview
                                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 transition-transform duration-300 group-open:rotate-180" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" /></svg>
                                    </summary>
                                    <div className="pt-2 pb-4 border-t border-slate-700/50">
                                        {renderMarkdown(project.overview)}
                                    </div>
                                </details>
