// --- Horizontal Row Component ---
const ContentRow: React.FC<{ title: React.ReactNode; children: React.ReactNode; }> = ({ title, children }) => {
    const scrollRef = useRef<HTMLDivElement>(null);

    const scroll = (direction: 'left' | 'right') => {
        if (scrollRef.current) {
            const scrollAmount = scrollRef.current.clientWidth * 0.8;
            scrollRef.current.scrollBy({
                left: direction === 'left' ? -scrollAmount : scrollAmount,
                behavior: 'smooth'
            });
        }
    };

    return (
        <div className="group relative my-8">
            <div className="text-xl md:text-2xl font-bold text-slate-100 mb-3 ml-4 md:ml-12">{title}</div>
            <button onClick={() => scroll('left')} className="absolute left-0 top-1/2 -translate-y-1/2 z-30 w-12 h-full bg-gradient-to-r from-black/80 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" aria-label="Scroll left">‹</button>
            <div ref={scrollRef} className="thumbnail-row flex items-center gap-2 md:gap-4 overflow-x-auto pb-4 pl-4 md:pl-12 pr-4 md:pr-12">
                {children}
            </div>
            <button onClick={() => scroll('right')} className="absolute right-0 top-1/2 -translate-y-1/2 z-30 w-12 h-full bg-gradient-to-l from-black/80 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" aria-label="Scroll right">›</button>
        </div>
    );
};

// --- Project Modal Component ---
const ProjectModal: React.FC<{ 
    project: Project | null; 
    onClose: () => void;
    onUpdateMedia: (projectId: string, index: number, file: File) => void;
    projectGalleryState: Record<string, string[]>;
    projectPosterState: Record<string, string>;
}> = ({ project, onClose, onUpdateMedia, projectGalleryState, projectPosterState }) => {
    const videoRef = useRef<HTMLVideoElement>(null);
    const [isVideoError, setIsVideoError] = useState(false);
    const [mediaIndex, setMediaIndex] = useState(0);
    const fileInputRef = useRef<HTMLInputElement>(null);
    const activeUploadIndex = useRef<number | null>(null);

    useEffect(() => {
        if (project) {
            setIsVideoError(false);
            setMediaIndex(0);
            document.body.style.overflow = 'hidden';
            setTimeout(() => {
                 videoRef.current?.play().catch(e => console.log("Autoplay was prevented."));
            }, 300);
        } else {
            document.body.style.overflow = 'auto';
        }
        return () => { document.body.style.overflow = 'auto'; };
    }, [project]);

    if (!project) return null;

    const currentPoster = projectPosterState[project.id] || project.poster;
    const currentGallery = projectGalleryState[project.id] || project.gallery || [];

    const media = [
        { type: 'video' as const, src: project.video, poster: currentPoster },
        ...currentGallery.map(url => ({ type: 'image' as const, src: url }))
    ];

    const handleUploadClick = (e: React.MouseEvent, index: number) => {
        e.stopPropagation();
        activeUploadIndex.current = index;
        fileInputRef.current?.click();
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file && activeUploadIndex.current !== null) {
            onUpdateMedia(project.id, activeUploadIndex.current, file);
        }
        if (e.target) e.target.value = '';
        activeUploadIndex.current = null;
    };

    const renderMarkdown = (text: string) => {
        const lines = text.split('\n').filter(line => line.trim() !== '');
        const elements = [];
        let i = 0;
        while (i < lines.length) {
            const line = lines[i];

            if (line.startsWith('### ')) {
                elements.push(<h3 key={i} className="text-xl font-semibold text-slate-200 mt-4 mb-2">{line.substring(4)}</h3>);
                i++;
            } else if (line.startsWith('## ')) {
                elements.push(<h2 key={i} className="text-2xl font-bold text-slate-100 mt-6 mb-3 border-b border-slate-700 pb-2">{line.substring(3)}</h2>);
                i++;
            } else if (line.startsWith('* ')) {
                const listItems = [];
                while (i < lines.length && lines[i].startsWith('* ')) {
                    const itemLine = lines[i].substring(2);
                    const parts = itemLine.split('**');
                    const styledLine = parts.map((part, p_idx) => p_idx % 2 === 1 ? <strong key={p_idx} className="text-slate-100">{part}</strong> : part);
                    listItems.push(<li key={i}>{styledLine}</li>);
                    i++;
                }
                elements.push(<ul key={`ul-${i}`} className="list-disc pl-6 space-y-2 mb-4 text-slate-300">{listItems}</ul>);
            } else if (line.startsWith('```')) {
                const codeLines = [];
                i++; // move past the opening ```
                while (i < lines.length && !lines[i].startsWith('```')) {
                    codeLines.push(lines[i]);
                    i++;
                }
                i++; // move past the closing ```
                elements.push(
                    <pre key={`pre-${i}`} className="code-block-container bg-slate-800/50 p-4 rounded-md my-4 overflow-x-auto">
                        <code className="text-sm text-cyan-300 font-mono">{codeLines.join('\n')}</code>
                    </pre>
                );
            }
            else {
                const parts = line.split('**');
                const styledLine = parts.map((part, p_idx) => p_idx % 2 === 1 ? <strong key={p_idx} className="text-slate-100">{part}</strong> : part);
                elements.push(<p key={i} className="text-slate-300 mb-4 leading-relaxed">{styledLine}</p>);
                i++;
            }
        }
        return elements;
    };

    const hasMultipleMedia = media.length > 1;
    const nextMedia = () => setMediaIndex(prev => (prev + 1) % media.length);
    const prevMedia = () => setMediaIndex(prev => (prev - 1 + media.length) % media.length);

    return (
        <div className="fixed inset-0 bg-slate-900 z-50 modal-enter modal-enter-active" role="dialog" aria-modal="true" aria-labelledby="project-title">
            <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept="image/*" />
            <div className="modal-content-enter modal-content-enter-active w-full h-full overflow-y-auto" onClick={e => { if(e.target === e.currentTarget) onClose() }}>
                <div className="relative w-full h-[60vh] bg-black">
                    <div className="w-full h-full overflow-hidden">
                        <div className="flex h-full transition-transform duration-700 cubic-bezier(0.4, 0, 0.2, 1)" style={{ transform: `translateX(-${mediaIndex * 100}%)` }}>
                            {media.map((item, index) => (
                                <div key={index} className="w-full h-full flex-shrink-0 relative">
                                    {item.type === 'video' ? (
                                        isVideoError ? (
                                            <img src={item.poster} alt={`${project.title} poster`} className="w-full h-full object-cover" />
                                        ) : (
                                            <video 
                                                ref={videoRef} 
                                                src={item.src} 
                                                poster={item.poster} 
                                                className="w-full h-full object-cover" 
                                                loop 
                                                muted 
                                                playsInline
                                                controls={mediaIndex === index}
                                                onError={() => setIsVideoError(true)}
                                            />
                                        )
                                    ) : (
                                        <img src={item.src} alt={`Project gallery image ${index}`} className="w-full h-full object-cover" loading="lazy" />
                                    )}
                                </div>
                            ))}
                        </div>
                    </div>

                    <div className="absolute inset-0 bg-gradient-to-t from-slate-900 to-transparent pointer-events-none"></div>
                    <button onClick={onClose} className="absolute top-6 right-6 w-10 h-10 bg-black/50 rounded-full text-white text-2xl z-20 hover:bg-red-600 transition-colors" aria-label="Close project details">&times;</button>
                    <h2 id="project-title" className="absolute bottom-8 left-8 text-3xl md:text-5xl font-bold text-white pointer-events-none z-10">{project.title}</h2>

                    {hasMultipleMedia && (
                        <>
                            <button onClick={prevMedia} className="carousel-btn left-4 opacity-0 group-hover:opacity-100 transition-opacity">‹</button>
                            <button onClick={nextMedia} className="carousel-btn right-4 opacity-0 group-hover:opacity-100 transition-opacity">›</button>
                            <div className="carousel-dots">
                                {media.map((_, index) => (
                                    <button key={index} onClick={() => setMediaIndex(index)} className={`w-2 h-2 rounded-full transition-all ${mediaIndex === index ? 'bg-white w-6' : 'bg-white/50 hover:bg-white/80'}`}></button>
                                ))}
                            </div>
                        </>
                    )}
                </div>
                <div className="max-w-5xl mx-auto p-8">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                        <div className="md:col-span-2">
                            <p className="text-slate-300 mb-4">{project.plot}</p>
                            <div className="flex flex-wrap gap-4 mb-8">
                                <a href={project.liveUrl} target="_blank" rel="noopener noreferrer" className="bg-white text-black font-bold py-2 px-6 rounded hover:bg-gray-200 transition-colors">Watch Now</a>

                                {project.infographicsUrl && project.infographicsUrl !== "#" && (
                                    <a href={project.infographicsUrl} target="_blank" rel="noopener noreferrer" className="bg-gray-600/50 text-white font-bold py-2 px-6 rounded hover:bg-gray-600/80 transition-colors">Infographics</a>
                                )}

                                {project.brochureUrl && project.brochureUrl !== "#" && (
                                    <a href={project.brochureUrl} target="_blank" rel="noopener noreferrer" className="bg-gray-600/50 text-white font-bold py-2 px-6 rounded hover:bg-gray-600/80 transition-colors">Brochure</a>
                                )}

                                {project.githubUrl && project.githubUrl !== "#" && (
                                    <a href={project.githubUrl} target="_blank" rel="noopener noreferrer" className="bg-gray-600/50 text-white font-bold py-2 px-6 rounded hover:bg-gray-600/80 transition-colors">GitHub</a>
                                )}
                            </div>

                            {/* Enhanced Gallery Grid */}
                            <div className="mb-10">
                                <h3 className="text-lg font-bold text-slate-200 mb-4 flex items-center gap-2">
                                    Visual Archives <span className="text-xs font-normal text-slate-500 bg-slate-800 px-2 py-0.5 rounded-full">{media.length} Clips</span>
                                </h3>
                                <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-5 gap-3">
                                    {/* Video/Poster Thumbnail */}
                                    <div 
                                        className={`relative aspect-square rounded-lg overflow-hidden cursor-pointer border-2 transition-all duration-300 group/thumb ${mediaIndex === 0 ? 'border-red-600 scale-95 ring-4 ring-red-600/20' : 'border-slate-800 hover:border-slate-500 opacity-60 hover:opacity-100'}`}
                                        onClick={() => setMediaIndex(0)}
                                    >
                                        <img src={currentPoster} alt="Poster" className="w-full h-full object-cover transition-transform duration-500 group-hover/thumb:scale-110" loading="lazy" />
                                        <div className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover/thumb:opacity-100 transition-opacity">
                                            <button onClick={(e) => handleUploadClick(e, 0)} className="bg-white/20 backdrop-blur-md p-1.5 rounded-full hover:bg-white/40 transition-colors" title="Replace Poster Image">
                                                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
                                            </button>
                                        </div>
                                        <div className="absolute top-1 left-1 bg-red-600 text-[8px] font-bold px-1.5 rounded-sm text-white">REEL</div>
                                    </div>

                                    {/* Gallery Item Thumbnails */}
                                    {currentGallery.map((url, idx) => (
                                        <div 
                                            key={idx} 
                                            className={`relative aspect-square rounded-lg overflow-hidden cursor-pointer border-2 transition-all duration-300 group/thumb ${mediaIndex === idx + 1 ? 'border-red-600 scale-95 ring-4 ring-red-600/20' : 'border-slate-800 hover:border-slate-500 opacity-60 hover:opacity-100'}`}
                                            onClick={() => setMediaIndex(idx + 1)}
                                        >
                                            <img src={url} alt={`Gallery ${idx + 1}`} className="w-full h-full object-cover transition-transform duration-500 group-hover/thumb:scale-110" loading="lazy" />
                                            <div className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover/thumb:opacity-100 transition-opacity">
                                                <button onClick={(e) => handleUploadClick(e, idx + 1)} className="bg-white/20 backdrop-blur-md p-1.5 rounded-full hover:bg-white/40 transition-colors" title="Replace Gallery Image">
                                                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
                                                </button>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                                <p className="text-[10px] text-slate-500 mt-2 italic">* Click upload icon to swap with your captured realtime pictures.</p>
                            </div>

                            {project.overview && (
                                <details className="group project-accordion bg-slate-800/30 rounded-lg p-1">
                                    <summary className="flex justify-between items-center cursor-pointer p-3 font-semibold text-slate-200 hover:bg-slate-800/50 rounded-md transition-colors">
                                        Project Blueprint & Insights
                                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 transition-transform duration-500 group-open:rotate-180" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" /></svg>
                                    </summary>
                                    <div className="p-4 border-t border-slate-700/50 animate-fade-in">
                                        {renderMarkdown(project.overview)}
                                    </div>
                                </details>
                            )}
                        </div>
                        <div className="text-sm space-y-6">
                            <div className="bg-slate-800/40 p-4 rounded-xl border border-slate-700/50">
                                <h4 className="text-slate-500 uppercase text-[10px] font-bold tracking-widest mb-3">Project Metadata</h4>
                                <p className="text-slate-400 mb-1">Architect: <span className="text-slate-100">{project.name}</span></p>
                                <p className="text-slate-400 mb-4">Focus Area: <span className="text-slate-100">{project.major}</span></p>
                                <h5 className="text-slate-500 uppercase text-[10px] font-bold tracking-widest mb-2">Structural Foundation</h5>
                                <div className="flex flex-wrap gap-1.5">
                                    {project.structuralComponents.map(comp => (
                                        <span key={comp} className="text-[10px] bg-slate-700/50 text-slate-300 px-2 py-0.5 rounded-md border border-slate-600/30">{comp}</span>
                                    ))}
                                </div>
                            </div>

                            <div className="flex flex-wrap gap-2">
                                {project.tags.map(tag => (
                                    <span key={tag} className="bg-red-600/10 text-red-500 border border-red-900/30 text-[10px] font-bold px-2.5 py-1 rounded-md uppercase tracking-wider">{tag}</span>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

