        const lines = text.split('\n');
        const elements = [];
        let i = 0;
        while (i < lines.length) {
            const line = lines[i];

            if (line.trim().startsWith('### ')) {
                elements.push(<h3 key={i} className="text-xl font-semibold text-slate-200 mt-4 mb-2">{line.trim().substring(4)}</h3>);
                i++;
