            .map(video => ({
                ...video,
                video_url: videoStates[video.id]?.status === 'ready' ? videoStates[video.id].url! : ''
            }))
            .filter(video => video.video_url); 
    }, [data, videoStates]);

    const openReel = (index: number) => {
        if (!data) return;
