                    style={{ transform: `translateY(${scrollY * 0.3}px)` }}
                    autoPlay 
                    loop 
                    muted 
                    playsInline 
                />
                <div className="absolute inset-0 bg-gradient-to-t from-black via-black/50 to-transparent"></div>
                <div className="relative z-10">
                    <h1 className="netflix-sans text-6xl md:text-9xl text-red-600 font-extrabold tracking-wider" style={{ textShadow: '0 0 15px rgba(0,0,0,0.7)' }}>
                        {data.hero.title}
                    </h1>
                    <p className="text-slate-300 mt-2 text-lg md:text-xl">A Professional Showcase</p>
                </div>
            </div>

            <main className="py-12 -mt-24 relative z-10">
                <div className="px-4 md:px-12 mb-8 max-w-3xl">
                    <p className="text-lg text-slate-300">Civil Engineer with over a decade of experience at landmark projects like the Grand Ethiopian Renaissance Dam (GERD) and the KOYSHA Hydroelectric project.</p>
                    <div className="flex items-center gap-4 mt-4">
                        <a href="mailto:mon14ye@gmail.com" className="bg-gray-600/50 text-white font-bold py-2 px-6 rounded hover:bg-gray-600/80 transition-colors">Contact Me</a>
                        <a href="/resume.pdf" target="_blank" rel="noopener noreferrer" className="bg-gray-600/50 text-white font-bold py-2 px-6 rounded hover:bg-gray-600/80 transition-colors">Resume</a>
